+    let mut footprint = 0u64;
+    let mut peak = 0u64;
+    #[cfg(target_os = "macos")]
+    {
+        #[repr(align(8))]
+        struct Usage([u8; 1024]);
+        extern "C" { fn proc_pid_rusage(pid: i32, flavor: i32, buffer: *mut u8) -> i32; }
