     ///Relocates the VM's trace, turning relocatable registers to numbered ones
+    pub fn prepare_streamed_relocation(&mut self) -> Result<Vec<usize>, MemoryError> {
+        self.vm.segments.compute_effective_sizes();
+        let table = self.vm.segments.relocate_segments()?;
+        self.vm.relocation_table = Some(table.clone());
+        Ok(table)
+    }
+
+    pub fn take_relocated_memory_entries(&mut self, table: Vec<usize>)
+        -> impl Iterator<Item = Result<(usize, Felt252), MemoryError>> {
+        let memory = std::mem::replace(&mut self.vm.segments.memory,
+            crate::vm::vm_memory::memory::Memory::new());
+        let table = std::sync::Arc::new(table);
+        memory.data.into_iter().enumerate().flat_map(move |(index, segment)| {
+            let table = table.clone();
+            segment.into_iter().enumerate().filter_map(move |(offset, cell)| {
+                cell.get_value().map(|value| {
+                    let address = relocate_address((index as isize, offset).into(), &table)?;
+                    let value = relocate_value(value, &table)?;
+                    Ok((address, value))
+                })
+            })
+        })
+    }
+
+    pub fn witness_buffer_bytes(&self) -> (usize, usize, usize) {
+        fn bytes<T>(v: &Vec<T>) -> usize { v.capacity() * std::mem::size_of::<T>() }
+        let memory = &self.vm.segments.memory;
+        let vm_bytes = memory.data.iter().chain(memory.temp_data.iter()).map(bytes).sum();
+        let relocated = bytes(&self.relocated_memory);
+        let trace = self.vm.trace.as_ref().map(bytes).unwrap_or(0)
+            + self.relocated_trace.as_ref().map(bytes).unwrap_or(0);
+        (vm_bytes, relocated, trace)
+    }
+
     pub fn relocate_trace(&mut self, relocation_table: &[usize]) -> Result<(), TraceError> {
         if self.relocated_trace.is_some() {
             return Err(TraceError::AlreadyRelocated);
         }
-
